from pathlib import Path
import subprocess

repo = Path("/home/deck/Old-Drive-Import/more repos/Repositories/blaine-azerothcore")
wiki = Path("/home/deck/Old-Drive-Import/Additional-Top-Level/Project_repositories/cics_v2/corpora/coding/sources/azerothcore_docs/official/wiki")
target = "7d540fc7e683c3bf34a2f465789f1b3df268b609"

def run(args, cwd):
    p = subprocess.run(args, cwd=cwd, capture_output=True, text=True)
    return (p.stdout or p.stderr).strip()

print("========== BLAINE-AZEROTHCORE HISTORY ==========")
