print("\n========== EXACT ENGINEERING RAG PIN REFERENCES ==========")
for base in [repo / "records", repo / "manifests", repo / "docs", repo]:
    if not base.exists():
        continue
    for path in sorted(base.rglob("*")):
        if not path.is_file() or ".git" in path.parts:
            continue
        try:
            text = path.read_text(errors="replace")
        except OSError:
            continue
        if target in text:
            print(f"\nMATCH: {path.relative_to(repo)}")
            for i, line in enumerate(text.splitlines(), 1):
                if target in line:
                    print(f"{i}: {line[:300]}")

print("\n========== ACQUISITION / VALIDATION RECORDS ==========")
for folder in ["records/executions", "records/validations", "records/decisions"]:
    base = repo / folder
    if base.exists():
        for path in sorted(base.glob("*azerothcore*")):
            print(path.relative_to(repo))

print("\n========== CICS_V2 WIKI TREE INVENTORY ==========")
count = 0
bytes_total = 0
docs_count = 0
for path in wiki.rglob("*"):
    if path.is_file():
        count += 1
        try:
            bytes_total += path.stat().st_size
        except OSError:
            pass
        if "docs" in path.relative_to(wiki).parts:
            docs_count += 1
print(f"Files: {count}")
print(f"Bytes: {bytes_total}")
print(f"Files beneath docs/: {docs_count}")
print("Top-level docs entries:")
docs = wiki / "docs"
if docs.exists():
    for item in sorted(docs.iterdir(), key=lambda p: p.name.lower())[:35]:
        print(("DIR  " if item.is_dir() else "FILE ") + item.name)

print("\n========== WIKI SOURCE METADATA CANDIDATES ==========")
for path in wiki.rglob("*"):
    if path.is_file() and path.name.lower() in {
        "readme.md", "source.json", "acquisition.json",
        "package.json", "gitinfo.json"
    }:
        print(path.relative_to(wiki))
